import { getChecksumConfiguration, resolveChecksumRuntimeConfig, } from "@smithy/core/dist-es/submodules/client/smithy-client/extensions/checksum";
import { getRetryConfiguration, resolveRetryRuntimeConfig } from "@smithy/core/dist-es/submodules/client/smithy-client/extensions/retry";
export const getDefaultExtensionConfiguration = (runtimeConfig) => {
    return Object.assign(getChecksumConfiguration(runtimeConfig), getRetryConfiguration(runtimeConfig));
};
export const getDefaultClientConfiguration = getDefaultExtensionConfiguration;
export const resolveDefaultRuntimeConfig = (config) => {
    return Object.assign(resolveChecksumRuntimeConfig(config), resolveRetryRuntimeConfig(config));
};
